package edu.hfut.appointment.dao;import java.util.*;import org.apache.ibatis.annotations.*;
public interface IssuanceMapper{
 @Select("SELECT issuance_operation_id operation_id,id appointment_id,issuance_actor_id actor_id,issuance_actor_token actor_token,issuance_payload payload,issuance_expected_version expected_version,issuance_phase phase,hold_reason,issuance_attempts attempts,qr_id,last_error_code FROM appointments WHERE id=#{id} AND issuance_operation_id IS NOT NULL")Map<String,Object>one(String id);
 @Select("SELECT issuance_operation_id operation_id,id appointment_id,issuance_actor_id actor_id,issuance_actor_token actor_token,issuance_payload payload,issuance_expected_version expected_version,issuance_phase phase,hold_reason,issuance_attempts attempts,qr_id,last_error_code FROM appointments WHERE issuance_operation_id=#{id}")Map<String,Object>operation(String id);
 @Update("UPDATE appointments SET issuance_operation_id=#{operationId},issuance_actor_id=#{actorId},issuance_actor_token=#{actorToken},issuance_payload=#{payload},issuance_expected_version=#{version},issuance_phase='PREPARE',hold_reason=NULL,issuance_attempts=0 WHERE id=#{appointmentId} AND issuance_operation_id IS NULL")int insert(Map<String,Object>row);
 @Select("SELECT id FROM appointments WHERE issuance_operation_id IS NOT NULL AND issuance_phase!='SUCCEEDED' AND hold_reason IS NULL AND (lease_until IS NULL OR lease_until<NOW(3)) LIMIT 20")List<String>due();
 @Update("UPDATE appointments SET lease_owner=#{owner},lease_until=DATE_ADD(NOW(3),INTERVAL 15 SECOND),issuance_attempts=issuance_attempts+1 WHERE id=#{id} AND issuance_operation_id IS NOT NULL AND (lease_until IS NULL OR lease_until<NOW(3))")int claim(@Param("id")String id,@Param("owner")String owner);
 @Update("UPDATE appointments SET issuance_phase=#{phase},qr_id=#{qr},last_error_code=NULL WHERE id=#{id} AND lease_owner=#{owner}")int phase(@Param("id")String id,@Param("owner")String owner,@Param("phase")String phase,@Param("qr")String qr);
 @Update("UPDATE appointments SET hold_reason=#{reason},last_error_code=#{reason} WHERE id=#{id} AND lease_owner=#{owner}")int hold(@Param("id")String id,@Param("owner")String owner,@Param("reason")String reason);
 @Update("UPDATE appointments SET last_error_code='RESULT_UNKNOWN' WHERE id=#{id} AND lease_owner=#{owner}")int unknown(@Param("id")String id,@Param("owner")String owner);
 @Update("UPDATE appointments SET lease_owner=NULL,lease_until=DATE_ADD(NOW(3),INTERVAL 2 SECOND) WHERE id=#{id} AND lease_owner=#{owner}")int release(@Param("id")String id,@Param("owner")String owner);
}
